<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Image Preview</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #090b10;
      --panel: #141923;
      --panel-strong: #1d2430;
      --text: #f5f7fb;
      --muted: #a8b3c7;
      --danger: #ff5f6d;
      --danger-strong: #e63946;
      --ring: #82aaff;
      --shadow: 0 24px 70px rgba(0, 0, 0, 0.55);
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      padding: 2rem;
      background:
        radial-gradient(circle at top left, rgba(130, 170, 255, 0.16), transparent 30rem),
        radial-gradient(circle at bottom right, rgba(255, 95, 109, 0.12), transparent 28rem),
        var(--bg);
      color: var(--text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      line-height: 1.5;
    }

    main {
      width: min(100%, 46rem);
    }

    .preview-card {
      overflow: hidden;
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 1.5rem;
      background: linear-gradient(145deg, rgba(29, 36, 48, 0.96), rgba(14, 18, 26, 0.96));
      box-shadow: var(--shadow);
    }

    .image-frame {
      margin: 0;
      background: #05070b;
    }

    .image-frame img {
      display: block;
      width: 100%;
      aspect-ratio: 16 / 10;
      object-fit: cover;
    }

    .card-content {
      display: flex;
      gap: 1.5rem;
      align-items: center;
      justify-content: space-between;
      padding: 1.5rem;
    }

    h1,
    h2,
    p {
      margin-top: 0;
    }

    h1 {
      margin-bottom: 0.25rem;
      font-size: clamp(1.5rem, 3vw, 2.35rem);
      line-height: 1.1;
    }

    p {
      color: var(--muted);
    }

    .card-content p,
    .dialog-panel p {
      margin-bottom: 0;
    }

    button {
      min-height: 2.75rem;
      border: 0;
      border-radius: 999px;
      padding: 0.75rem 1.15rem;
      color: var(--text);
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      transition: background 160ms ease, box-shadow 160ms ease, transform 160ms ease;
    }

    button:hover {
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 3px solid var(--ring);
      outline-offset: 3px;
    }

    .trigger,
    .danger-button {
      background: linear-gradient(135deg, var(--danger), var(--danger-strong));
      box-shadow: 0 12px 30px rgba(230, 57, 70, 0.28);
    }

    .trigger:hover,
    .danger-button:hover {
      box-shadow: 0 16px 38px rgba(230, 57, 70, 0.38);
    }

    .secondary-button {
      background: var(--panel-strong);
      box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.12);
    }

    .secondary-button:hover {
      background: #283142;
    }

    .dialog-backdrop {
      position: fixed;
      inset: 0;
      display: none;
      place-items: center;
      padding: 1.25rem;
      background: rgba(2, 4, 8, 0.78);
      backdrop-filter: blur(10px);
    }

    .dialog-backdrop.is-open {
      display: grid;
    }

    .dialog-panel {
      width: min(100%, 28rem);
      border: 1px solid rgba(255, 255, 255, 0.12);
      border-radius: 1.25rem;
      padding: 1.5rem;
      background: linear-gradient(180deg, #202838, #111722);
      box-shadow: var(--shadow);
    }

    .dialog-panel h2 {
      margin-bottom: 0.5rem;
      font-size: 1.35rem;
      line-height: 1.2;
    }

    .dialog-actions {
      display: flex;
      flex-wrap: wrap;
      justify-content: flex-end;
      gap: 0.75rem;
      margin-top: 1.5rem;
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    @media (max-width: 36rem) {
      body {
        padding: 1rem;
      }

      .card-content,
      .dialog-actions {
        align-items: stretch;
        flex-direction: column;
      }

      .trigger,
      .dialog-actions button {
        width: 100%;
      }
    }
  </style>
</head>
<body>
  <main>
    <article class="preview-card" aria-labelledby="page-title">
      <figure class="image-frame">
        <img
          src="https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&amp;fit=crop&amp;w=1200&amp;q=80"
          alt="A quiet cabin beside a lake at sunset">
      </figure>
      <div class="card-content">
        <div>
          <h1 id="page-title">Lakeside sunset</h1>
          <p>Image preview from your library.</p>
        </div>
        <button class="trigger" type="button" aria-haspopup="dialog">
          Delete image
        </button>
      </div>
    </article>
  </main>

  <div class="dialog-backdrop" id="delete-dialog-backdrop">
    <section
      class="dialog-panel"
      role="dialog"
      aria-modal="true"
      aria-labelledby="dialog-title"
      aria-describedby="dialog-description"
      tabindex="-1">
      <h2 id="dialog-title">Delete this image?</h2>
      <p id="dialog-description">
        This will remove "Lakeside sunset" from your library. This action cannot be undone.
      </p>
      <div class="dialog-actions">
        <button class="secondary-button" type="button" data-close-dialog>Cancel</button>
        <button class="danger-button" type="button">Delete image</button>
      </div>
    </section>
  </div>

  <script>
    const openButton = document.querySelector('.trigger');
    const backdrop = document.querySelector('#delete-dialog-backdrop');
    const dialog = backdrop.querySelector('[role="dialog"]');
    const closeButton = backdrop.querySelector('[data-close-dialog]');
    const focusableSelector = 'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])';
    let previousFocus = null;

    function openDialog() {
      previousFocus = document.activeElement;
      backdrop.classList.add('is-open');
      dialog.focus();
    }

    function closeDialog() {
      backdrop.classList.remove('is-open');

      if (previousFocus) {
        previousFocus.focus();
      }
    }

    openButton.addEventListener('click', openDialog);
    closeButton.addEventListener('click', closeDialog);

    backdrop.addEventListener('click', (event) => {
      if (event.target === backdrop) {
        closeDialog();
      }
    });

    document.addEventListener('keydown', (event) => {
      if (!backdrop.classList.contains('is-open')) {
        return;
      }

      if (event.key === 'Escape') {
        closeDialog();
        return;
      }

      if (event.key !== 'Tab') {
        return;
      }

      const focusableElements = Array.from(dialog.querySelectorAll(focusableSelector));
      const firstElement = focusableElements[0];
      const lastElement = focusableElements[focusableElements.length - 1];

      if (event.shiftKey && document.activeElement === firstElement) {
        event.preventDefault();
        lastElement.focus();
      } else if (!event.shiftKey && document.activeElement === lastElement) {
        event.preventDefault();
        firstElement.focus();
      }
    });
  </script>
</body>
</html>
